Contract GenerateLoanLetterAndAgreementModule::createLoanAccount(loanaccountid:Integer,balance:Real,status:LoanAccountStatus[NORMAL|HASPAIDINFULL]): Boolean {
          definition:
          foundLoanAccount:LoanAccount = LoanAccount.allInstance()->any(la | la.LoanAccountID=loanaccountid)


            postcondition:
          foundLoanAccount.oclIsUndefined()=false and foundLoanAccount.Balance=balance and foundLoanAccount.Status=status and result=true or let la:LoanAccount in la.oclIsNew() and la.LoanAccountID=loanaccountid and la.Balance=balance and la.Status=status and LoanAccount.allInstance()->includes(la) and result=true

        }
